mapper.select:
select * from (
select sm.*, m.machine_code, m.machine_name
from T_XWYY_SPECIFY_MACHINE sm
left join T_XWYY_MACHINE_INFO m on sm.machine_id = m.id
where sm.DEL_FLAG = 0
and m.DEL_FLAG = 0

    and INSTR(BIG_ROLL_CODE, #{bigRollCode,jdbcType=VARCHAR}) > 0


    and MACHINE_ID = #{machineId}


    and LINE_TYPE = #{lineType}


    and JOB_TYPE = #{jobType}



    order by sm.CREATE_TIME DESC

) t

    order by ${orderStr}

mapper.update:
merge into T_XWYY_SPECIFY_MACHINE a USING (
select #{SpecifyMachine.bigRollCode,jdbcType=VARCHAR} BIG_ROLL_CODE, #{SpecifyMachine.machineId,jdbcType=DOUBLE} machine_id, #{SpecifyMachine.lineType,jdbcType=VARCHAR} line_type, #{SpecifyMachine.jobType,jdbcType=VARCHAR} job_type, #{SpecifyMachine.createBy,jdbcType=VARCHAR} create_by, #{SpecifyMachine.createTime,jdbcType=DATE} create_time, #{SpecifyMachine.updateBy,jdbcType=VARCHAR} update_by, #{SpecifyMachine.updateTime,jdbcType=DATE} update_time, #{SpecifyMachine.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.BIG_ROLL_CODE = b.BIG_ROLL_CODE and b.machine_id = a.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.line_type = b.line_type, a.job_type = b.job_type, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.BIG_ROLL_CODE, a.machine_id, a.line_type, a.job_type, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_PUBLIC.NEXTVAL, b.BIG_ROLL_CODE, b.machine_id, b.line_type, b.job_type, b.create_by, sysdate, b.remark, '0')
